#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sys/stat.h>
#include <errno.h>
#include <limits.h>

#define AES_KEY_SIZE 32
#define AES_IV_SIZE 16
#define MAX_PATH_COMPONENT 255
#define STORAGE_ROOT "/var/lib/imgstore/encrypted/"

typedef struct {
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[AES_IV_SIZE];
    char storage_root[PATH_MAX];
} crypto_ctx_t;

typedef struct {
    char album_id[64];
    char image_name[MAX_PATH_COMPONENT];
    unsigned int width;
    unsigned int height;
    unsigned char *pixel_data;
    size_t data_len;
} image_job_t;

static int normalize_path_component(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    size_t input_len = strlen(input);

    if (input_len == 0 || input_len >= outlen)
        return -1;

    for (i = 0; i < input_len && j < outlen - 1; i++) {
        if (input[i] == '\0') break;
        /* Skip null bytes and control characters */
        if (input[i] < 0x20 && input[i] != 0) continue;
        /* Reject obvious traversal */
        if (input[i] == '/' || input[i] == '\\') return -1;
        output[j++] = input[i];
    }
    output[j] = '\0';
    return 0;
}

static int validate_album_id(const char *album_id) {
    size_t len = strlen(album_id);
    if (len == 0 || len > 63) return -1;
    for (size_t i = 0; i < len; i++) {
        char c = album_id[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '-' || c == '_'))
            return -1;
    }
    return 0;
}

static int build_storage_path(const crypto_ctx_t *ctx, const image_job_t *job,
                              char *path_out, size_t path_out_len) {
    char safe_album[64];
    char safe_name[MAX_PATH_COMPONENT];

    if (validate_album_id(job->album_id) != 0)
        return -1;

    if (normalize_path_component(job->image_name, safe_name, sizeof(safe_name)) != 0)
        return -1;

    /* Check for dot-dot after normalization */
    if (strstr(safe_name, "..") != NULL)
        return -1;

    strncpy(safe_album, job->album_id, sizeof(safe_album) - 1);
    safe_album[sizeof(safe_album) - 1] = '\0';

    int written = snprintf(path_out, path_out_len, "%s%s/%s.enc",
                           ctx->storage_root, safe_album, safe_name);

    if (written < 0 || (size_t)written >= path_out_len)
        return -1;

    /* Resolve and verify the path stays within storage root */
    char resolved[PATH_MAX];
    char *dir_end = strrchr(path_out, '/');
    if (!dir_end) return -1;

    char dir_path[PATH_MAX];
    size_t dir_len = (size_t)(dir_end - path_out);
    if (dir_len >= PATH_MAX) return -1;
    memcpy(dir_path, path_out, dir_len);
    dir_path[dir_len] = '\0';

    /* Create directory if needed */
    mkdir(dir_path, 0750);

    if (realpath(dir_path, resolved) == NULL)
        return -1;

    /* Verify prefix - compare against the canonical storage root */
    char resolved_root[PATH_MAX];
    if (realpath(ctx->storage_root, resolved_root) == NULL)
        return -1;

    size_t root_len = strlen(resolved_root);
    if (strncmp(resolved, resolved_root, root_len) != 0)
        return -1;

    /* Ensure we didn't just match a prefix of a different directory name */
    if (resolved[root_len] != '/' && resolved[root_len] != '\0')
        return -1;

    /* Rebuild final path with resolved directory */
    const char *filename = dir_end + 1;
    snprintf(path_out, path_out_len, "%s/%s", resolved, filename);

    return 0;
}

static int encrypt_and_store(const crypto_ctx_t *ctx, const unsigned char *data,
                             size_t data_len, const char *output_path) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return -1;

    unsigned char *ciphertext = malloc(data_len + EVP_MAX_BLOCK_LENGTH);
    if (!ciphertext) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    /* Generate a fresh, unique IV for each encryption operation.
     * Reusing a fixed IV with the same key in CBC mode is insecure. */
    unsigned char iv[AES_IV_SIZE];
    if (RAND_bytes(iv, AES_IV_SIZE) != 1) {
        free(ciphertext);
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    int len, ciphertext_len;

    if (EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL,
                           ctx->key, iv) != 1)
        goto err;

    if (EVP_EncryptUpdate(cipher_ctx, ciphertext, &len, data, (int)data_len) != 1)
        goto err;
    ciphertext_len = len;

    if (EVP_EncryptFinal_ex(cipher_ctx, ciphertext + len, &len) != 1)
        goto err;
    ciphertext_len += len;

    FILE *fp = fopen(output_path, "wb");
    if (!fp) goto err;

    /* Store the per-message IV alongside the ciphertext for decryption. */
    fwrite(iv, 1, AES_IV_SIZE, fp);
    fwrite(ciphertext, 1, (size_t)ciphertext_len, fp);
    fclose(fp);

    free(ciphertext);
    EVP_CIPHER_CTX_free(cipher_ctx);
    return 0;

err:
    free(ciphertext);
    EVP_CIPHER_CTX_free(cipher_ctx);
    return -1;
}

int process_image_upload(crypto_ctx_t *ctx, image_job_t *job) {
    if (!ctx || !job || !job->pixel_data || job->data_len == 0)
        return -1;

    /* Simulate image processing: resize, watermark, etc. */
    unsigned char *processed = malloc(job->data_len);
    if (!processed) return -1;
    memcpy(processed, job->pixel_data, job->data_len);

    char output_path[PATH_MAX];
    if (build_storage_path(ctx, job, output_path, sizeof(output_path)) != 0) {
        free(processed);
        return -1;
    }

    int ret = encrypt_and_store(ctx, processed, job->data_len, output_path);
    free(processed);
    return ret;
}

int init_crypto_context(crypto_ctx_t *ctx, const char *root_override) {
    if (!ctx) return -1;

    if (RAND_bytes(ctx->key, AES_KEY_SIZE) != 1) return -1;
    /* Note: ctx->iv is no longer used for encryption; a fresh IV is
     * generated per operation in encrypt_and_store(). Initialize it
     * to avoid leaving uninitialized data in the struct. */
    if (RAND_bytes(ctx->iv, AES_IV_SIZE) != 1) return -1;

    const char *root = root_override ? root_override : STORAGE_ROOT;
    strncpy(ctx->storage_root, root, PATH_MAX - 1);
    ctx->storage_root[PATH_MAX - 1] = '\0';

    return 0;
}
